# -*- coding: utf-8 -*-
"""PyPacker 自动生成的运行时 hook，请勿手动修改。

作用：程序启动时自动为常见 GUI 框架设置窗口图标，
      使窗口和任务栏图标与 exe 文件图标保持一致。

支持框架：
    · tkinter / customtkinter
    · PyQt5 / PyQt6
    · PySide2 / PySide6
    · wxPython
"""
import base64
import os
import sys
import tempfile

_ICON_B64 = """"""
_ICON_NAME = "_pypacker_embedded.ico"


# --------------------------------------------------------------------------- #
def _ensure_icon_file():
    """把 base64 数据还原成实际 .ico 文件，返回其绝对路径。"""
    # 优先用 PyInstaller 的解压目录（onefile 模式下是 _MEIPASS）
    base = getattr(sys, "_MEIPASS", None)
    if not base:
        # 未打包（源码直跑）——写到用户临时目录
        base = os.path.join(tempfile.gettempdir(), "_pypacker_runtime")
        try:
            os.makedirs(base, exist_ok=True)
        except Exception:
            return None

    path = os.path.join(base, _ICON_NAME)
    if not os.path.exists(path):
        try:
            data = base64.b64decode(_ICON_B64)
            with open(path, "wb") as f:
                f.write(data)
        except Exception:
            return None
    return path


# --------------------------------------------------------------------------- #
#  tkinter / customtkinter
# --------------------------------------------------------------------------- #
def _patch_tkinter():
    try:
        import tkinter
    except ImportError:
        return

    icon_path = _ensure_icon_file()
    if not icon_path:
        return

    # Tk 主窗口
    try:
        _orig_tk_init = tkinter.Tk.__init__
    except AttributeError:
        return

    def _tk_init(self, *a, **kw):
        _orig_tk_init(self, *a, **kw)
        try:
            self.iconbitmap(icon_path)
        except Exception:
            try:
                self.wm_iconbitmap(icon_path)
            except Exception:
                pass

    tkinter.Tk.__init__ = _tk_init

    # Toplevel 子窗口
    try:
        _orig_tl_init = tkinter.Toplevel.__init__

        def _tl_init(self, *a, **kw):
            _orig_tl_init(self, *a, **kw)
            try:
                self.iconbitmap(icon_path)
            except Exception:
                pass

        tkinter.Toplevel.__init__ = _tl_init
    except Exception:
        pass


# --------------------------------------------------------------------------- #
#  Qt 家族（PyQt5 / PyQt6 / PySide2 / PySide6）
# --------------------------------------------------------------------------- #
def _patch_qt():
    icon_path = _ensure_icon_file()
    if not icon_path:
        return

    targets = [
        ("PyQt5.QtWidgets",  "QApplication", "PyQt5.QtGui",  "QIcon"),
        ("PyQt6.QtWidgets",  "QApplication", "PyQt6.QtGui",  "QIcon"),
        ("PySide2.QtWidgets", "QApplication", "PySide2.QtGui", "QIcon"),
        ("PySide6.QtWidgets", "QApplication", "PySide6.QtGui", "QIcon"),
    ]

    for modname, clsname, guimod, iconname in targets:
        try:
            widgets = __import__(modname, fromlist=[clsname])
            gui = __import__(guimod, fromlist=[iconname])
            App = getattr(widgets, clsname)
            Icon = getattr(gui, iconname)
        except Exception:
            continue

        if getattr(App, "_pypacker_patched", False):
            continue

        # 用工厂函数避免闭包晚绑定
        def _make_init(_orig, _Icon, _path):
            def _init(self, *a, **kw):
                _orig(self, *a, **kw)
                try:
                    self.setWindowIcon(_Icon(_path))
                except Exception:
                    pass
            return _init

        App.__init__ = _make_init(App.__init__, Icon, icon_path)
        App._pypacker_patched = True


# --------------------------------------------------------------------------- #
#  wxPython
# --------------------------------------------------------------------------- #
def _patch_wx():
    try:
        import wx
    except ImportError:
        return

    icon_path = _ensure_icon_file()
    if not icon_path:
        return

    if getattr(wx.Frame, "_pypacker_patched", False):
        return

    _orig = wx.Frame.__init__

    def _init(self, *a, **kw):
        _orig(self, *a, **kw)
        try:
            self.SetIcon(wx.Icon(icon_path))
        except Exception:
            pass

    wx.Frame.__init__ = _init
    wx.Frame._pypacker_patched = True


# --------------------------------------------------------------------------- #
#  执行所有 patch
# --------------------------------------------------------------------------- #
_patch_tkinter()
_patch_qt()
_patch_wx()
